import math

def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()

def build_agent(sandbox):
    return sandbox.get_seeker_body()

def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {'last_tx': 0.0, 'last_ty': 0.0, 'tvx': 0.0, 'tvy': 0.0}
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Update target velocity estimate
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    # Get corridor bounds and rendezvous slots
    x_min, x_max = sandbox.get_corridor_bounds()
    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Determine target goal based on phase
    if step_count < 110:
        # Activation phase: move to midpoint of activation zone
        desired_gx = 15.0  # Midpoint of [13.0, 17.0]
        desired_gx = max(x_min + 0.02, min(desired_gx, x_max - 0.02))
        gx, gy = desired_gx, 1.35
    elif in_slot:
        # Rendezvous phase: track target
        gx, gy = tx, ty
    else:
        # Post-activation navigation: maintain position within activation zone
        desired_gx = 13.1 if (step_count // 120) % 2 == 0 else 13.5
        desired_gx = max(x_min + 0.02, min(desired_gx, x_max - 0.02))
        gx, gy = desired_gx, 1.35

    # PD controller with adjusted gains
    if in_slot:
        fx = 300.0 * (gx - sx) + 60.0 * (state['tvx'] - svx)
        fy = 300.0 * (gy - sy) + 60.0 * (state['tvy'] - svy)
    else:
        fx = 100.0 * (gx - sx) - 20.0 * svx
        fy = 100.0 * (gy - sy) - 20.0 * svy

    # Thrust saturation during critical phases
    if step_count < 110 or not in_slot:
        mag = math.sqrt(fx**2 + fy**2)
        if mag > 100.0:
            fx, fy = fx * 100.0 / mag, fy * 100.0 / mag

    # Apply thrust
    sandbox.apply_seeker_force(fx, fy)
